namespace chrome_apps {
namespace api {

// static
bool ChromeAppsGeneratedSchemas::IsGenerated(base::StringPiece name) {
  return !Get(name).empty();
}

// static
base::StringPiece ChromeAppsGeneratedSchemas::Get(base::StringPiece name) {
  static constexpr auto kSchemas = base::MakeFixedFlatMap<base::StringPiece, base::StringPiece>({
    {"arcAppsPrivate", kArcAppsPrivate},
    {"browser", kBrowser},
    {"enterprise.remoteApps", kEnterpriseRemoteApps},
    {"mediaGalleries", kMediaGalleries},
    {"syncFileSystem", kSyncFileSystem},
  });
  auto it = kSchemas.find(name);
  return it != kSchemas.end() ? it->second : base::StringPiece();
}

}  // namespace api
}  // namespace chrome_apps
